const embassyHtml = $('Fetch Thai Embassy Moscow').first().json.data || '';
const consularHtml = $('Fetch Thai Consular MFA').first().json.data || '';

function htmlToText(html) {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(br|\/p|\/div|\/li|\/h1|\/h2|\/h3|\/h4|\/tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const embassyText = htmlToText(embassyHtml).slice(0, 30000);
const consularText = htmlToText(consularHtml).slice(0, 30000);

return [{json:{
  embassy_url:'https://moscow.thaiembassy.org/en/publicservice/revision-of-thailand-s-visa-exemption-and-visa-on-arrival-schemes',
  consular_url:'https://consular.mfa.go.th/th/content/1-9-69-00',
  combined_context:`SOURCE 1 — ROYAL THAI EMBASSY MOSCOW\n${embassyText}\n\nSOURCE 2 — THAILAND DEPARTMENT OF CONSULAR AFFAIRS\n${consularText}`,
  checked_at:new Date().toISOString()
}}];

