const r=$input.first().json;
const msg=(r.output||[]).find(x=>x.type==='message');
const out=msg?.content?.find(x=>x.type==='output_text');
if(!out?.text) throw new Error('Missing OpenAI output');
const d=JSON.parse(out.text);
const c=$('Prepare Official Context').first().json;
let status=String(d.status||'unclear');
let hasChange=d.has_change===true;
let effective=d.effective_date||null;
const decision=String(d.decision_status||'unclear');
if(status==='changed' && (!hasChange || !['approved','published_or_effective'].includes(decision) || !effective)){
  status='unclear'; hasChange=false; effective=null;
}
if(status!=='changed'){hasChange=false; effective=null;}
const cur=Number(d.current_stay_days);
const fut=d.future_stay_days==null?null:Number(d.future_stay_days);
const fingerprint=[status,Number.isFinite(cur)?cur:'',Number.isFinite(fut)?fut:'',effective||'',decision].join('|');
const sources=[c.embassy_url,c.consular_url].filter(Boolean);
return [{json:{
 key:'thailand_russia_visa',has_change:hasChange,status,
 current_rule:String(d.current_rule||'').trim(),current_stay_days:Number.isFinite(cur)?cur:null,
 future_rule:d.future_rule==null?null:String(d.future_rule).trim(),future_stay_days:Number.isFinite(fut)?fut:null,
 effective_date:effective,decision_status:decision,summary:String(d.summary||'').trim(),
 confidence:String(d.confidence||'low'),sources,sources_text:sources.join('\n'),
 state_fingerprint:fingerprint,checked_at:c.checked_at||new Date().toISOString()
}}];

const current=$('Parse Visa Classification').first().json;
const previous=$input.first().json||{};
const prev=String(previous.last_state_fingerprint||'').trim();
const now=String(current.state_fingerprint||'').trim();
const first=!prev;
const changed=prev!==now;
let notify_type='no_change';
let notify_reason='State unchanged';
if(first||changed){
  if(current.status==='changed'&&current.has_change===true){notify_type='changed';notify_reason='Official change detected';}
  else if(current.status==='unclear'){notify_type='unclear';notify_reason='Unconfirmed information detected';}
}
return [{json:{...current,previous_fingerprint:prev,state_changed:changed,is_first_run:first,notify_type,notify_reason}}];
